-- CRTeamSkins.lua: co-op team paint through EXU material clones. Lua 5.1.
--
-- Co-op only (network games), driven from CRCoop.Update(); every peer applies
-- the same rule locally, nothing is sent over the network:
--   * team 1 (host/leader team) keeps the units' own paint,
--   * the host's own ship gets green digital camouflage,
--   * each human guest team (2-4) gets its own solid tint on every craft it
--     owns; AI teams never paint.
--
-- A unit material <src> takes part when "<src>_tm" exists (Materials/
-- CR_TeamSkins.material, generated by Tools/Build-TeamSkins.py: the unit's own
-- CR_BZBase aliases plus a TeamMask). For a skin, "<src>_tm" is cloned once to
-- "<src>@crteam_<key>" and the skin is written to the clone's teamPaint uniform
-- (Shaders/CR_static_ibl.program, default 0), which openshim_enhanced_base-sm4
-- (TEAM_PAINT_ENABLED) reads. Specular stays the unit's own:
--   alpha <= 1.5      off
--   rgb 0, alpha 2+b  camo from the mask RGB, brightness b
--   rgb tint, alpha 2 solid tint, keeping the hull's own shading
-- Only the en-high* techniques paint; medium/low/og-* show the units' own paint.
--
-- Sub-entities showing any other material (CRSurfaceEffects / CRReactive
-- per-craft clones, cockpit, glass) belong to someone else and are left alone.
local T = {}

T.SWEEP = 1.0
T.SUFFIX = "_tm"
T.HOST = { key = "host", r = 0, g = 0, b = 0, a = 2.65 }      -- camo, ISDFC green brightness 0.65
T.GUEST = {
    [2] = { key = "t2", r = 0.80, g = 0.18, b = 0.12, a = 2.0 },  -- red
    [3] = { key = "t3", r = 0.20, g = 0.38, b = 0.85, a = 2.0 },  -- blue
    [4] = { key = "t4", r = 0.90, g = 0.68, b = 0.12, a = 2.0 },  -- gold
}

local NEEDED = { "GetSubEntityCount", "GetSubEntityMaterial", "SetSubEntityMaterial",
    "MaterialExists", "CloneMaterial", "SetMaterialShaderVector" }
local tracked = {}    -- handle -> { key, index, want }
local teamBase = {}   -- source material -> "<src>_tm" | false
local cloneDone = {}  -- clone name -> true once tinted
local nextSweep = 0

local function call(fn, ...)
    if type(fn) ~= "function" then return nil end
    local ok, value = pcall(fn, ...)
    if ok then return value end
    return nil
end

local function lib()
    local e = T.exu or package.loaded.exu
    if type(e) ~= "table" then return nil end
    for _, name in ipairs(NEEDED) do
        if type(e[name]) ~= "function" then return nil end
    end
    return e
end

-- "avtank00@crteam_t2" -> "avtank00"
local function source(name) return (string.gsub(name, "@crteam_.*$", "")) end

local function baseOf(exu, src)
    local b = teamBase[src]
    if b == nil then
        b = (call(exu.MaterialExists, src .. T.SUFFIX) == true) and (src .. T.SUFFIX) or false
        teamBase[src] = b
    end
    return b or nil
end

local function ensure(exu, src, skin)
    local b = baseOf(exu, src)
    if not b then return nil end
    local dst = src .. "@crteam_" .. skin.key
    if cloneDone[dst] then return dst end
    if call(exu.MaterialExists, dst) ~= true then
        if call(exu.CloneMaterial, b, dst) ~= true or call(exu.MaterialExists, dst) ~= true then return nil end
    end
    -- every pass that declares teamPaint (the en-high wrappers); 0 = none did
    local changed = call(exu.SetMaterialShaderVector, dst, "teamPaint", skin.r, skin.g, skin.b, skin.a, -1, -1)
    if type(changed) ~= "number" or changed < 1 then return nil end
    cloneDone[dst] = true
    return dst
end

-- skin nil = back to the source materials. Returns the first sub-entity taken
-- part (index, material) so the sweep can spot engine resets cheaply.
local function apply(exu, h, skin)
    local n = call(exu.GetSubEntityCount, h)
    if type(n) ~= "number" then return nil end
    local first, firstWant
    for i = 0, n - 1 do
        local cur = call(exu.GetSubEntityMaterial, h, i)
        if type(cur) == "string" then
            local src = source(cur)
            if baseOf(exu, src) then
                local want = skin and ensure(exu, src, skin) or src
                if want ~= cur then call(exu.SetSubEntityMaterial, h, i, want) end
                if first == nil then first, firstWant = i, want end
            end
        end
    end
    return first, firstWant
end

local function skinFor(h, hostShip, coop)
    if h == hostShip then return T.HOST end
    local team = call(GetTeamNum, h)
    if team == coop.GetLeaderTeam() then return nil end
    -- AI allies/enemies on teams 2-4 keep their own paint
    if not (coop.IsHumanTeam and call(coop.IsHumanTeam, team)) then return nil end
    return T.GUEST[team]
end

local function hostShipOf(coop)
    local leader, ship = coop.GetLeaderTeam(), nil
    coop.ForEachPlayerHandle(function(h)
        if ship == nil and call(GetTeamNum, h) == leader then ship = h end
    end)
    return ship
end

-- ~1 s sweep over every craft: spawns, respawns, team changes (sniped or
-- hijacked craft), the host changing ships, and engine material resets.
function T.Update(coop)
    if coop == nil or not coop.IsNetworkGame() then return end
    local t = call(GetTime) or 0
    if t < nextSweep then return end
    nextSweep = t + T.SWEEP
    local exu = lib()
    if exu == nil then return end
    local hostShip = hostShipOf(coop)
    for h in AllCraft() do  -- craft only: scrap/props/buildings never change team or reset paint
        local skin = skinFor(h, hostShip, coop)
        local key = skin and skin.key or nil
        local rec = tracked[h]
        local redo
        if rec == nil then
            redo = skin ~= nil
        elseif rec.key ~= key then
            redo = true
        elseif rec.index == nil then
            redo = false  -- nothing paintable on this object (pilot, building)
        else
            local cur = call(exu.GetSubEntityMaterial, h, rec.index)
            -- reapply only over our own names; another module's clone is left alone
            redo = cur ~= rec.want and type(cur) == "string" and baseOf(exu, source(cur)) ~= nil
        end
        if redo then
            local count = call(exu.GetSubEntityCount, h)
            if type(count) == "number" and count > 0 then  -- 0/nil: entity not built yet, retry
                local index, want = apply(exu, h, skin)
                tracked[h] = skin ~= nil and { key = key, index = index, want = want } or nil
            end
        end
    end
    for h in pairs(tracked) do
        if call(IsValid, h) ~= true then tracked[h] = nil end
    end
end

-- After a load every handle is new and the clone cache may be stale.
function T.Reset()
    tracked, teamBase, cloneDone, nextSweep = {}, {}, {}, 0
end

function T.TrackedCount()
    local n = 0
    for _ in pairs(tracked) do n = n + 1 end
    return n
end

return T
